package org.brightstats.stats;

import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class MixtureChecks {
    private static int checks;
    private static void check(boolean value){checks++;if(!value)throw new AssertionError("Mixture check "+checks);}
    private static void close(double a,double b,double tolerance){checks++;if(!Double.isFinite(a)||!Double.isFinite(b)||Math.abs(a-b)>tolerance*Math.max(1,Math.abs(b)))throw new AssertionError("Mixture "+a+" != "+b);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid mixture accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonArray cases=new JsonArray();Random random=new Random(20261121);List<String> names=List.of("X","Y","Z");for(boolean intercept:new boolean[]{false,true}){
            double[][] data=new double[240][3];for(double[] row:data){boolean first=random.nextDouble()<.6;row[0]=random.nextGaussian();row[1]=(intercept?(first?.6:-.5):0)+(first?.9:-.8)*row[0]+.2*random.nextGaussian();row[2]=(intercept?(first?.4:-.3):0)+.2*row[0]+(first?.7:-.5)*row[1]+.2*random.nextGaussian();}
            for(int equations=1;equations<=2;equations++)for(int k=1;k<=2;k++)for(var initialization:FiniteMixture.Initialization.values()){
                var edges=equations==1?List.of(new PlsSem.Edge(0,1)):List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));var options=new FiniteMixture.Options(k,3,1000,1e-8,295948,intercept,.001,2,initialization,FiniteMixture.Stopping.OBSERVED_LOG_LIKELIHOOD);var fit=FiniteMixture.fit(data,names,edges,options,null);check(fit.converged());check(fit.starts().size()==3);check(fit.segments().size()==k);check(fit.assignments().length==data.length);for(double[] row:fit.probabilities())close(Arrays.stream(row).sum(),1,2e-14);for(int step=1;step<fit.trace().size();step++)check(fit.trace().get(step).logLikelihood()>=fit.trace().get(step-1).logLikelihood()-1e-8);check(fit.criteria().parameters()==k-1+k*(edges.size()+equations+(intercept?equations:0)));check(fit.criteria().referenceParameters()==k-1+k*(edges.size()+equations));if(k==2)check(fit.criteria().normalizedEntropy()>=0&&fit.criteria().normalizedEntropy()<=1);if(k==1&&intercept){var ordinary=OlsRegression.fit(Arrays.stream(data).map(row->new double[]{row[0]}).toArray(double[][]::new),Arrays.stream(data).mapToDouble(row->row[1]).toArray());var equation=fit.segments().get(0).equations().get(0);close(equation.intercept(),ordinary.coefficients()[0],1e-12);close(equation.coefficients()[0],ordinary.coefficients()[1],1e-12);close(equation.variance(),ordinary.residualSumOfSquares()/data.length,1e-12);}
                JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(data));test.add("names",gson.toJsonTree(names));test.add("edges",gson.toJsonTree(edges));test.add("options",gson.toJsonTree(options));test.add("result",gson.toJsonTree(fit));cases.add(test);
            }
        }
        double[][] indicators=new double[180][6];for(double[] row:indicators){boolean first=random.nextDouble()<.6;double x=random.nextGaussian(),y=(first?.9:-.7)*x+.25*random.nextGaussian(),z=.3*x+.6*y+.3*random.nextGaussian();for(int j=0;j<6;j++)row[j]=4+new double[]{x,x,y,y,z,z}[j]+.15*random.nextGaussian();}var blocks=List.of(new PlsSem.Block("X",new int[]{0,1},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{2,3},PlsSem.Mode.A),new PlsSem.Block("Z",new int[]{4,5},PlsSem.Mode.A));var structure=List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));for(boolean raw:new boolean[]{false,true}){var settings=new FiniteMixture.Options(2,3,1000,1e-8,295948,raw,.001,2,FiniteMixture.Initialization.RANDOM_SIMPLEX,FiniteMixture.Stopping.OBSERVED_LOG_LIKELIHOOD);var fit=PlsMixture.fit(indicators,blocks,structure,PlsSem.Options.defaults(),settings,raw,null);check(fit.mixture().converged());for(var segment:fit.segmentEffects())close(segment.totalEffects()[0][2],segment.paths()[0][2]+segment.paths()[0][1]*segment.paths()[1][2],1e-12);JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(fit.scoreObservations()));test.add("names",gson.toJsonTree(names));test.add("edges",gson.toJsonTree(structure));test.add("options",gson.toJsonTree(settings));test.add("result",gson.toJsonTree(fit.mixture()));test.add("originalData",gson.toJsonTree(indicators));test.add("blocks",gson.toJsonTree(blocks));test.add("plsMixture",gson.toJsonTree(fit));cases.add(test);}
        double[][] simple={{-2,-1.8},{-1,-.9},{0,0},{1,.9},{2,1.8},{3,2.7}};var edges=List.of(new PlsSem.Edge(0,1));var floorOptions=new FiniteMixture.Options(1,1,20,1e-8,42,false,.1,1,FiniteMixture.Initialization.RANDOM_SIMPLEX,FiniteMixture.Stopping.EXPECTED_COMPLETE_LOG_LIKELIHOOD);var floor=FiniteMixture.fit(simple,List.of("X","Y"),edges,floorOptions,null);check(floor.segments().get(0).equations().get(0).varianceConstrained());check(!floor.criteria().convergedInteriorCandidate());var provisional=FiniteMixture.fit(simple,List.of("X","Y"),edges,new FiniteMixture.Options(1,1,1,1e-8,42,false,.1,1,FiniteMixture.Initialization.RANDOM_SIMPLEX,FiniteMixture.Stopping.OBSERVED_LOG_LIKELIHOOD),null);check(!provisional.converged());
        for(var fit:List.of(floor,provisional)){JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(simple));test.add("names",gson.toJsonTree(List.of("X","Y")));test.add("edges",gson.toJsonTree(edges));test.add("options",gson.toJsonTree(fit.options()));test.add("result",gson.toJsonTree(fit));cases.add(test);}
        reject(()->FiniteMixture.fit(simple,List.of("X","Y"),List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(1,0)),floorOptions,null));reject(()->FiniteMixture.fit(simple,List.of("X","Y"),edges,new FiniteMixture.Options(10,1,10,1e-7,42,false,.001,2,FiniteMixture.Initialization.RANDOM_SIMPLEX,FiniteMixture.Stopping.OBSERVED_LOG_LIKELIHOOD),null));reject(()->new FiniteMixture.Options(0,1,10,1e-7,42,false,.001,2,FiniteMixture.Initialization.RANDOM_SIMPLEX,FiniteMixture.Stopping.OBSERVED_LOG_LIKELIHOOD));Thread.currentThread().interrupt();try{FiniteMixture.fit(simple,List.of("X","Y"),edges,floorOptions,null);throw new AssertionError("Mixture ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"mixture_cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
